import assert from 'node:assert/strict';
import fs from 'node:fs';
import {createClient} from '@sanity/client';
import {productCode} from '../coffee/lib/catalog.js';
import {buildRfqMessage} from '../coffee/lib/rfq-message.js';
import {productGalleryMedia} from '../coffee/lib/product-media.js';
const slug='12oz-16oz-insulated-coffee-tumbler-with-silicone-grip';
const id='coffee-'+slug;
const source=createClient({projectId:'rbq1eoim',dataset:'ecopak-coffee-cups-production',apiVersion:'2026-10-26',useCdn:false});
const src=await source.fetch('*[_id==$id][0]{...,"imageUrl":mainImage.asset->url,"galleryImages":galleryImages[]{_key,_type,alt,"imageUrl":image.asset->url}}',{id:'product-'+slug});
assert.equal(src.galleryImages.length,24);assert.equal(src.colors.length,10);
assert.deepEqual(src.variants.map(v=>v.size),['12oz','16oz']);assert.deepEqual(src.variants.map(v=>v.priceUsd),[3.39,3.63]);
assert.equal(src.fromPriceLabel,'US$3.39-3.63 / pc EXW');
assert.ok(src.videoUrls[0].includes('fc1305511c24c23fa8efe9aa383c9477c2524332'));
assert.equal(src.imageUrl,src.galleryImages[0].imageUrl);assert.equal(src.videoPosterUrl,src.imageUrl);
assert.ok(src.galleryImages.every(v=>v.imageUrl&&v.alt));
const token=JSON.parse(fs.readFileSync('/Users/xiaziwen/.config/sanity/config.json','utf8')).authToken;
const target=createClient({projectId:'12npkiv4',dataset:'production',apiVersion:'2026-10-26',useCdn:false,token,maxRetries:0});
const before=await target.fetch('*[_type=="coffeeProduct"]');assert.ok(!before.some(p=>p._id===id),'New product already exists; inspect before replacing.');
const old=before.find(p=>p.slug==='10oz-compact-insulated-coffee-tumbler-with-slide-lid');assert.equal(old.isActive,false);
const cm13=before.find(p=>productCode(p.slug)==='CM-13');const cm08=before.find(p=>productCode(p.slug)==='CM-08');assert.equal(cm08.collectionRanks.find(r=>r.slug==='insulated-tumblers').position,9);
const {_createdAt,_updatedAt,_rev,_id,_type,mainImage,videoFile,videoPoster,...content}=src;
const doc={...content,_id:id,_type:'coffeeProduct',slug,isActive:true,sourceProject:'rbq1eoim'};
fs.mkdirSync('../backups',{recursive:true});const backup='../backups/coffee-before-new-cm10-'+Date.now()+'.json';fs.writeFileSync(backup,JSON.stringify(before,null,2));
await target.transaction().create(doc).patch(cm13._id,p=>p.ifRevisionId(cm13._rev).set({collectionRanks:cm13.collectionRanks.map(r=>r.slug==='insulated-tumblers'?{...r,position:8.25}:r)})).commit();
const after=await target.fetch('*[_type=="coffeeProduct"]');const actual=after.find(p=>p._id===id);
assert.deepEqual(actual.galleryImages,src.galleryImages);assert.deepEqual(actual.variants,src.variants);assert.deepEqual(actual.colors,src.colors);
for(const k of ['name','description','shortDescription','detailText','specificationsText','faqText','features','tags','imageUrl','videoPosterUrl','videoUrls'])assert.deepEqual(actual[k],doc[k],k);
const media=productGalleryMedia(actual.galleryImages,actual.videoUrls,actual.videoPosterUrl);assert.equal(media.length,25);assert.equal(media[1].type,'video');assert.equal(media[1].poster,actual.imageUrl);
const rfq=buildRfqMessage({productSlug:slug,selectedOption:'16oz',quantity:100},[actual]);assert.equal(rfq.modelSummary,'CM-10');assert.ok(rfq.text.includes('16oz'));
const sorted=after.filter(p=>p.isActive!==false).sort((a,b)=>a.collectionRanks[0].position-b.collectionRanks[0].position);const pos=sorted.findIndex(p=>p._id===id);assert.equal(sorted[pos-1]._id,cm13._id);assert.equal(sorted[pos+1]._id,cm08._id);
for(const p of before){const a=after.find(x=>x._id===p._id);for(const k of Object.keys(p).filter(k=>!['_rev','_updatedAt',...(p._id===cm13._id?['collectionRanks']:[])].includes(k)))assert.deepEqual(a[k],p[k],p._id+' '+k);}
console.log('PASS: new CM10 synced; 24 images; video second; matching main/poster; 10 colours; 12oz $3.39 / 16oz $3.63; RFQ CM-10; CM13 → CM10 → CM08; old CM10 inactive; all other data preserved. Backup:',backup);
